test('dashboard', async (t) => {
  const asOf = '2026-10-07';

  await t.test('returns empty dashboard for no invoices', () => {
    const result = dashboard([], asOf);
    assert.deepStrictEqual(result.counts, { draft: 0, issued: 0, partially_paid: 0, paid: 0 });
    assert.strictEqual(result.outstanding, 0);
    assert.deepStrictEqual(result.overdue, { count: 0, amount: 0 });
    assert.deepStrictEqual(result.topCustomers, []);
  });

  await t.test('counts invoices by status', () => {
    const invoices = [
      { customerId: 'C-001', status: 'draft', lines: [], payments: [] },
      { customerId: 'C-002', status: 'issued', lines: [], payments: [] },
      { customerId: 'C-003', status: 'partially_paid', lines: [], payments: [] },
      { customerId: 'C-001', status: 'paid', lines: [], payments: [] },
      { customerId: 'C-002', status: 'draft', lines: [], payments: [] },
    ];
    const result = dashboard(invoices, asOf);
    assert.strictEqual(result.counts.draft, 2);
    assert.strictEqual(result.counts.issued, 1);
    assert.strictEqual(result.counts.partially_paid, 1);
    assert.strictEqual(result.counts.paid, 1);
  });

  await t.test('calculates outstanding total for issued and partially_paid', () => {
    const invoices = [
      {
        customerId: 'C-001',
        status: 'issued',
        lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
        payments: [],
