        customerId: 'C-002',
        status: 'issued',
        dueDate: '2026-10-15',
        lines: [{ qty: 1, unitPrice: 50000, discountPercent: 0, vatRate: 0 }],
        payments: [],
      },
      {
        customerId: 'C-003',
        status: 'issued',
        dueDate: '2026-10-15',
        lines: [{ qty: 1, unitPrice: 20000, discountPercent: 0, vatRate: 0 }],
        payments: [],
